import{_ as s,o as t,c as e,a4 as l}from"./chunks/framework.BUqnS5H7.js";const g=JSON.parse('{"title":"WAL 日志与崩溃恢复","description":"","frontmatter":{"doc_id":"pg-wal","title":"WAL 日志与崩溃恢复"},"headers":[],"relativePath":"postgresql/02-architecture/chapter-02-wal.md","filePath":"postgresql/02-architecture/chapter-02-wal.md"}'),n={name:"postgresql/02-architecture/chapter-02-wal.md"};function i(p,a,r,c,d,h){return t(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="wal-日志与崩溃恢复" tabindex="-1" data-src-line="2" data-src-file="postgresql/02-architecture/chapter-02-wal.md">WAL 日志与崩溃恢复 <a class="header-anchor" href="#wal-日志与崩溃恢复" aria-label="Permalink to &quot;WAL 日志与崩溃恢复&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><p data-src-line="4" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>核心问题：</strong> 数据库如何保证在突然断电时不丢失已提交的事务？答案是 WAL（Write-Ahead Logging）— 先写日志，后写数据。WAL 不仅是崩溃恢复的基石，也是流复制和 PITR 的基础。理解 WAL 的原理，是掌握 PG 高可用架构的前提。</p></blockquote><hr><h2 id="_1-wal-核心原理" tabindex="-1" data-src-line="8" data-src-file="postgresql/02-architecture/chapter-02-wal.md">1. WAL 核心原理 <a class="header-anchor" href="#_1-wal-核心原理" aria-label="Permalink to &quot;1. WAL 核心原理&quot;">​</a></h2><p data-src-line="10" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>WAL（Write-Ahead Logging）</strong> 的核心规则只有一条：</p><blockquote data-src-line="12" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><p data-src-line="12" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>对数据页的修改，必须先将对应的 WAL 记录写入持久化存储，然后才能将修改后的数据页写入磁盘。</strong></p></blockquote><p data-src-line="14" data-src-file="postgresql/02-architecture/chapter-02-wal.md">这就是所谓的 <strong>WAL 先写协议（Write-Ahead Protocol）</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务执行流程:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  BEGIN</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>  修改数据页 (在 Shared Buffers 中)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>  生成 WAL 记录 → 写入 WAL Buffer</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>  COMMIT</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├──→ WAL Buffer → 刷入 WAL 文件 (pg_wal/)   ← 必须先完成</span></span>
<span class="line"><span>    │                     │</span></span>
<span class="line"><span>    │                     ▼</span></span>
<span class="line"><span>    │               fsync 确保落盘                 ← 此时事务才算提交</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └──→ 脏页在 Shared Buffers 中等待              ← 后续由 Bg Writer / Checkpointer 刷盘</span></span></code></pre></div><h3 id="为什么需要-wal" tabindex="-1" data-src-line="38" data-src-file="postgresql/02-architecture/chapter-02-wal.md">为什么需要 WAL？ <a class="header-anchor" href="#为什么需要-wal" aria-label="Permalink to &quot;为什么需要 WAL？&quot;">​</a></h3><table tabindex="0"><thead data-src-line="40" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="40" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">问题</th><th style="text-align:left;">没有 WAL 的情况</th><th style="text-align:left;">有 WAL 的情况</th></tr></thead><tbody data-src-line="42" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="42" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;">事务提交后断电</td><td style="text-align:left;">数据可能还在内存，未写入磁盘 → 丢失</td><td style="text-align:left;">WAL 已落盘 → 可恢复</td></tr><tr data-src-line="43" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;">脏页写到一半断电</td><td style="text-align:left;">数据页损坏 → 不一致</td><td style="text-align:left;">从 WAL 重放 → 恢复一致状态</td></tr><tr data-src-line="44" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;">随机 I/O vs 顺序 I/O</td><td style="text-align:left;">每次修改都要随机写数据页</td><td style="text-align:left;">WAL 是顺序写，性能更高</td></tr></tbody></table><hr><h2 id="_2-wal-文件结构" tabindex="-1" data-src-line="48" data-src-file="postgresql/02-architecture/chapter-02-wal.md">2. WAL 文件结构 <a class="header-anchor" href="#_2-wal-文件结构" aria-label="Permalink to &quot;2. WAL 文件结构&quot;">​</a></h2><p data-src-line="50" data-src-file="postgresql/02-architecture/chapter-02-wal.md">WAL 日志存储在 <code>$PGDATA/pg_wal/</code> 目录下，由一系列 <strong>段文件（Segment File）</strong> 组成。</p><h3 id="段文件基本属性" tabindex="-1" data-src-line="52" data-src-file="postgresql/02-architecture/chapter-02-wal.md">段文件基本属性 <a class="header-anchor" href="#段文件基本属性" aria-label="Permalink to &quot;段文件基本属性&quot;">​</a></h3><table tabindex="0"><thead data-src-line="54" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="54" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">属性</th><th style="text-align:left;">值</th></tr></thead><tbody data-src-line="56" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="56" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>单个段文件大小</strong></td><td style="text-align:left;">16MB（默认，编译时可通过 <code>--with-wal-segsize</code> 修改）</td></tr><tr data-src-line="57" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>命名格式</strong></td><td style="text-align:left;"><code>{时间线ID}{逻辑段号}{物理段号}</code>，各 8 位十六进制</td></tr><tr data-src-line="58" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>示例</strong></td><td style="text-align:left;"><code>000000010000000000000001</code>（时间线 1，逻辑段 0，物理段 1）</td></tr><tr data-src-line="59" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>时间线 ID</strong></td><td style="text-align:left;">24 位，标识数据库历史分支（PITR/故障切换后递增）</td></tr><tr data-src-line="60" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>逻辑段号</strong></td><td style="text-align:left;">高 32 位</td></tr><tr data-src-line="61" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>物理段号</strong></td><td style="text-align:left;">低 32 位</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pg_wal/</span></span>
<span class="line"><span>├── 000000010000000000000001   # 时间线1, 第1个16MB段</span></span>
<span class="line"><span>├── 000000010000000000000002   # 时间线1, 第2个16MB段</span></span>
<span class="line"><span>├── 000000010000000000000003   # 时间线1, 第3个16MB段</span></span>
<span class="line"><span>├── 000000010000000000000004   # 当前正在写入</span></span>
<span class="line"><span>└── archive_status/</span></span>
<span class="line"><span>    ├── 000000010000000000000001.done   # 已归档</span></span>
<span class="line"><span>    └── 000000010000000000000002.ready   # 等待归档</span></span></code></pre></div><h3 id="wal-记录结构" tabindex="-1" data-src-line="74" data-src-file="postgresql/02-architecture/chapter-02-wal.md">WAL 记录结构 <a class="header-anchor" href="#wal-记录结构" aria-label="Permalink to &quot;WAL 记录结构&quot;">​</a></h3><p data-src-line="76" data-src-file="postgresql/02-architecture/chapter-02-wal.md">每条 WAL 记录包含：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────┐</span></span>
<span class="line"><span>│         WAL Record Header        │</span></span>
<span class="line"><span>│  - xl_tot_len:   记录总长度      │</span></span>
<span class="line"><span>│  - xl_xid:       事务 ID         │</span></span>
<span class="line"><span>│  - xl_prev:      前一条 WAL 的LSN│</span></span>
<span class="line"><span>│  - xl_rmid:      资源管理器 ID   │</span></span>
<span class="line"><span>│  - xl_info:      操作类型标志    │</span></span>
<span class="line"><span>│  - xl_tot_len:   CRC 校验        │</span></span>
<span class="line"><span>├──────────────────────────────────┤</span></span>
<span class="line"><span>│         Block Reference          │</span></span>
<span class="line"><span>│  - 关联的数据文件和页面号         │</span></span>
<span class="line"><span>├──────────────────────────────────┤</span></span>
<span class="line"><span>│         Record Data              │</span></span>
<span class="line"><span>│  - 实际的操作数据                 │</span></span>
<span class="line"><span>│  (如: INSERT 的行数据)            │</span></span>
<span class="line"><span>└──────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_3-lsn-log-sequence-number" tabindex="-1" data-src-line="99" data-src-file="postgresql/02-architecture/chapter-02-wal.md">3. LSN（Log Sequence Number） <a class="header-anchor" href="#_3-lsn-log-sequence-number" aria-label="Permalink to &quot;3. LSN（Log Sequence Number）&quot;">​</a></h2><p data-src-line="101" data-src-file="postgresql/02-architecture/chapter-02-wal.md">LSN 是 WAL 日志中每条记录的唯一标识，本质上是一个 <strong>64 位字节偏移量</strong>，指向该记录在 WAL 流中的物理位置。</p><h3 id="lsn-格式" tabindex="-1" data-src-line="103" data-src-file="postgresql/02-architecture/chapter-02-wal.md">LSN 格式 <a class="header-anchor" href="#lsn-格式" aria-label="Permalink to &quot;LSN 格式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LSN 格式: 前32位/后32位 (十六进制)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>示例: 0/15D6878</span></span>
<span class="line"><span>      │ │</span></span>
<span class="line"><span>      │ └── 低 32 位 (段内偏移)</span></span>
<span class="line"><span>      └──── 高 32 位 (逻辑段号)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>字节偏移 = 高32位 × 16MB + 低32位</span></span></code></pre></div><h3 id="lsn-的用途" tabindex="-1" data-src-line="116" data-src-file="postgresql/02-architecture/chapter-02-wal.md">LSN 的用途 <a class="header-anchor" href="#lsn-的用途" aria-label="Permalink to &quot;LSN 的用途&quot;">​</a></h3><table tabindex="0"><thead data-src-line="118" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="118" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">用途</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="120" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="120" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>WAL 记录排序</strong></td><td style="text-align:left;">LSN 递增，标识操作的先后顺序</td></tr><tr data-src-line="121" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>数据页版本标记</strong></td><td style="text-align:left;">每个数据页的 <code>pd_lsn</code> 记录最后修改它的 WAL LSN</td></tr><tr data-src-line="122" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>恢复起点</strong></td><td style="text-align:left;">Checkpoint 记录的 LSN 标识恢复应从哪里开始重放</td></tr><tr data-src-line="123" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>复制同步</strong></td><td style="text-align:left;">备库报告已重放的 LSN，主库据此判断同步状态</td></tr><tr data-src-line="124" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>脏页判断</strong></td><td style="text-align:left;">若 WAL 记录的 LSN &gt; 数据页的 <code>pd_lsn</code>，说明该页需要重放此 WAL</td></tr></tbody></table><h3 id="查看当前-lsn" tabindex="-1" data-src-line="126" data-src-file="postgresql/02-architecture/chapter-02-wal.md">查看当前 LSN <a class="header-anchor" href="#查看当前-lsn" aria-label="Permalink to &quot;查看当前 LSN&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 当前 WAL 写入位置</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_current_wal_lsn();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 当前 WAL 文件名和偏移</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_current_wal_insert_lsn();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_current_wal_flush_lsn();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看数据页的 LSN</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lsn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_buffercache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> relfilenode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16384</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 两个 LSN 之间的字节差</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0/15D6878&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::pg_lsn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0/15D6800&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::pg_lsn;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- = 120 字节</span></span></code></pre></div><h2 id="_4-wal-写入流程" tabindex="-1" data-src-line="143" data-src-file="postgresql/02-architecture/chapter-02-wal.md">4. WAL 写入流程 <a class="header-anchor" href="#_4-wal-写入流程" aria-label="Permalink to &quot;4. WAL 写入流程&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Backend Process                WAL Buffers              pg_wal/</span></span>
<span class="line"><span>    │                             │                       │</span></span>
<span class="line"><span>    │── 生成 WAL 记录 ──────────→   │                       │</span></span>
<span class="line"><span>    │   (写入 WAL Buffer)          │                       │</span></span>
<span class="line"><span>    │                             │                       │</span></span>
<span class="line"><span>    │── XLogInsert() ───────────→ │                       │</span></span>
<span class="line"><span>    │                             │                       │</span></span>
<span class="line"><span>    │── XLogFlush() (提交时) ────→ │                       │</span></span>
<span class="line"><span>    │                             │── 刷入 WAL 文件 ────→  │</span></span>
<span class="line"><span>    │                             │   (write + fsync)     │</span></span>
<span class="line"><span>    │                             │                       │</span></span>
<span class="line"><span>    │←── 返回 (事务已提交) ──────   │                       │</span></span></code></pre></div><h3 id="wal-写入的三种路径" tabindex="-1" data-src-line="160" data-src-file="postgresql/02-architecture/chapter-02-wal.md">WAL 写入的三种路径 <a class="header-anchor" href="#wal-写入的三种路径" aria-label="Permalink to &quot;WAL 写入的三种路径&quot;">​</a></h3><table tabindex="0"><thead data-src-line="162" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="162" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">路径</th><th style="text-align:left;">触发条件</th><th style="text-align:left;">关键参数</th></tr></thead><tbody data-src-line="164" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="164" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>同步写入</strong></td><td style="text-align:left;">事务提交时（<code>synchronous_commit = on</code>）</td><td style="text-align:left;"><code>wal_sync_method</code>（fsync/fdatasync 等）</td></tr><tr data-src-line="165" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>异步写入</strong></td><td style="text-align:left;"><code>synchronous_commit = off</code> 时，提交不等 fsync</td><td style="text-align:left;">有数据丢失风险（最多 <code>wal_writer_delay</code> 时间窗口）</td></tr><tr data-src-line="166" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>WAL Buffer 满</strong></td><td style="text-align:left;">WAL Buffer 达到阈值自动写出</td><td style="text-align:left;"><code>wal_buffers</code></td></tr></tbody></table><h3 id="关键参数" tabindex="-1" data-src-line="168" data-src-file="postgresql/02-architecture/chapter-02-wal.md">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to &quot;关键参数&quot;">​</a></h3><table tabindex="0"><thead data-src-line="170" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="170" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="172" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="172" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>wal_level</code></td><td style="text-align:left;">replica</td><td style="text-align:left;">WAL 记录的详细程度</td></tr><tr data-src-line="173" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>wal_buffers</code></td><td style="text-align:left;">-1 (自动)</td><td style="text-align:left;">WAL 缓冲区大小，通常为 shared_buffers 的 1/32</td></tr><tr data-src-line="174" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>wal_writer_delay</code></td><td style="text-align:left;">200ms</td><td style="text-align:left;">WAL Writer 唤醒间隔</td></tr><tr data-src-line="175" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>synchronous_commit</code></td><td style="text-align:left;">on</td><td style="text-align:left;">是否等待 WAL fsync 完成</td></tr><tr data-src-line="176" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>wal_sync_method</code></td><td style="text-align:left;">平台相关</td><td style="text-align:left;">fsync/fdatasync/open_datasync 等</td></tr><tr data-src-line="177" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>commit_delay</code></td><td style="text-align:left;">0 (μs)</td><td style="text-align:left;">组提交延迟，批量 fsync</td></tr><tr data-src-line="178" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><code>commit_siblings</code></td><td style="text-align:left;">5</td><td style="text-align:left;">组提交的最小并发事务数</td></tr></tbody></table><blockquote data-src-line="180" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><p data-src-line="180" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>性能建议：</strong> <code>synchronous_commit = off</code> 可以显著提升写入性能，但断电时最多丢失 <code>wal_writer_delay</code>（默认 200ms）时间内的事务。对数据安全性要求不高的场景（如日志表）可以考虑。</p></blockquote><h2 id="_5-崩溃恢复流程" tabindex="-1" data-src-line="182" data-src-file="postgresql/02-architecture/chapter-02-wal.md">5. 崩溃恢复流程 <a class="header-anchor" href="#_5-崩溃恢复流程" aria-label="Permalink to &quot;5. 崩溃恢复流程&quot;">​</a></h2><p data-src-line="184" data-src-file="postgresql/02-architecture/chapter-02-wal.md">当 PG 检测到非正常关闭（缺少 <code>postmaster.pid</code> 或控制文件标记不一致），会自动进入恢复模式。</p><h3 id="恢复步骤" tabindex="-1" data-src-line="186" data-src-file="postgresql/02-architecture/chapter-02-wal.md">恢复步骤 <a class="header-anchor" href="#恢复步骤" aria-label="Permalink to &quot;恢复步骤&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PG 启动</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>读取 pg_control (控制文件)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>判断是否需要恢复? ──否──→ 正常启动</span></span>
<span class="line"><span>  │是</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>定位最后一个 Checkpoint 记录</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>从 Checkpoint 的 redo LSN 开始</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>顺序读取 WAL 记录 ──────────────────────────┐</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  ├──→ 对每条 WAL 记录:                      │</span></span>
<span class="line"><span>  │    1. 读取关联的数据页                    │</span></span>
<span class="line"><span>  │    2. 比较 LSN:                          │</span></span>
<span class="line"><span>  │       - 数据页 pd_lsn ≥ WAL LSN → 跳过   │</span></span>
<span class="line"><span>  │       - 数据页 pd_lsn &lt; WAL LSN → 重放   │</span></span>
<span class="line"><span>  │    3. 应用修改到数据页                    │</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  │←─────────────────────────────────────────┘</span></span>
<span class="line"><span>  │ (循环直到 WAL 结尾)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>所有 WAL 重放完毕</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>回滚未提交的事务 (通过 CLOG)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>恢复正常服务</span></span></code></pre></div><h3 id="恢复时间估算" tabindex="-1" data-src-line="226" data-src-file="postgresql/02-architecture/chapter-02-wal.md">恢复时间估算 <a class="header-anchor" href="#恢复时间估算" aria-label="Permalink to &quot;恢复时间估算&quot;">​</a></h3><p data-src-line="228" data-src-file="postgresql/02-architecture/chapter-02-wal.md">恢复时间取决于需要重放的 WAL 量：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>恢复时间 ≈ (当前 LSN - 最近 Checkpoint LSN) / WAL 重放速率</span></span>
<span class="line"><span></span></span>
<span class="line"><span>影响因素:</span></span>
<span class="line"><span>- WAL 重放速率: 约 100~500 MB/s (取决于磁盘和 CPU)</span></span>
<span class="line"><span>- Checkpoint 间隔: checkpoint_timeout = 5min, max_wal_size = 1GB</span></span>
<span class="line"><span>- 理想情况: 恢复时间 &lt; 1 分钟</span></span></code></pre></div><blockquote data-src-line="239" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><p data-src-line="239" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>调优关联：</strong> 增大 <code>max_wal_size</code> 可以减少 Checkpoint 频率，提升写入性能，但会延长崩溃恢复时间。需要在写入性能和恢复时间之间权衡。</p></blockquote><h2 id="_6-wal-level-配置" tabindex="-1" data-src-line="241" data-src-file="postgresql/02-architecture/chapter-02-wal.md">6. wal_level 配置 <a class="header-anchor" href="#_6-wal-level-配置" aria-label="Permalink to &quot;6. wal_level 配置&quot;">​</a></h2><p data-src-line="243" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><code>wal_level</code> 控制 WAL 记录的详细程度，直接影响功能特性和性能。</p><table tabindex="0"><thead data-src-line="245" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="245" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">级别</th><th style="text-align:left;">记录内容</th><th style="text-align:left;">支持的功能</th><th style="text-align:left;">性能影响</th></tr></thead><tbody data-src-line="247" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="247" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>minimal</strong></td><td style="text-align:left;">仅记录崩溃恢复所需的最少信息</td><td style="text-align:left;">基本恢复。不支持复制、PITR、pg_basebackup</td><td style="text-align:left;">最小</td></tr><tr data-src-line="248" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>replica</strong></td><td style="text-align:left;">记录恢复 + 流复制所需的信息</td><td style="text-align:left;">流复制、PITR、归档、pg_basebackup</td><td style="text-align:left;">中等（默认）</td></tr><tr data-src-line="249" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>logical</strong></td><td style="text-align:left;">在 replica 基础上附加逻辑解码信息</td><td style="text-align:left;">逻辑复制、pg_recvlogical、变更数据捕获（CDC）</td><td style="text-align:left;">较高</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看当前 wal_level</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW wal_level;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 修改 wal_level (需重启)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SYSTEM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> wal_level </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;logical&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 然后重启 PostgreSQL</span></span></code></pre></div><blockquote data-src-line="260" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><p data-src-line="260" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>Java 生态关联：</strong> 如果使用 Debezium 等 CDC 工具进行变更数据捕获（如同步到 Elasticsearch、Kafka），必须设置 <code>wal_level = logical</code>。这对写入性能有约 5~10% 的影响。</p></blockquote><h2 id="_7-wal-与复制的关系" tabindex="-1" data-src-line="262" data-src-file="postgresql/02-architecture/chapter-02-wal.md">7. WAL 与复制的关系 <a class="header-anchor" href="#_7-wal-与复制的关系" aria-label="Permalink to &quot;7. WAL 与复制的关系&quot;">​</a></h2><p data-src-line="264" data-src-file="postgresql/02-architecture/chapter-02-wal.md">WAL 是 PG 所有复制方案的基础。</p><h3 id="复制架构" tabindex="-1" data-src-line="266" data-src-file="postgresql/02-architecture/chapter-02-wal.md">复制架构 <a class="header-anchor" href="#复制架构" aria-label="Permalink to &quot;复制架构&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────┐         ┌─────────────────────┐</span></span>
<span class="line"><span>│     Primary          │         │     Standby          │</span></span>
<span class="line"><span>│                      │         │                      │</span></span>
<span class="line"><span>│  Backend Process     │   WAL   │  Startup Process     │</span></span>
<span class="line"><span>│       │              │  Stream │       │              │</span></span>
<span class="line"><span>│       ▼              │ ──────→ │       ▼              │</span></span>
<span class="line"><span>│  WAL Buffer          │         │  重放 WAL 记录       │</span></span>
<span class="line"><span>│       │              │         │       │              │</span></span>
<span class="line"><span>│       ▼              │         │       ▼              │</span></span>
<span class="line"><span>│  pg_wal/             │         │  pg_wal/ (接收)      │</span></span>
<span class="line"><span>│                      │         │       │              │</span></span>
<span class="line"><span>│                      │         │       ▼              │</span></span>
<span class="line"><span>│                      │         │  数据页 (应用修改)    │</span></span>
<span class="line"><span>└─────────────────────┘         └─────────────────────┘</span></span></code></pre></div><h3 id="同步-vs-异步复制" tabindex="-1" data-src-line="285" data-src-file="postgresql/02-architecture/chapter-02-wal.md">同步 vs 异步复制 <a class="header-anchor" href="#同步-vs-异步复制" aria-label="Permalink to &quot;同步 vs 异步复制&quot;">​</a></h3><table tabindex="0"><thead data-src-line="287" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="287" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><th style="text-align:left;">模式</th><th style="text-align:left;">行为</th><th style="text-align:left;">数据安全</th><th style="text-align:left;">性能</th></tr></thead><tbody data-src-line="289" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><tr data-src-line="289" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>同步复制</strong></td><td style="text-align:left;">主库等待备库确认 WAL 已写入后才返回提交</td><td style="text-align:left;">零数据丢失</td><td style="text-align:left;">较高延迟</td></tr><tr data-src-line="290" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><td style="text-align:left;"><strong>异步复制</strong></td><td style="text-align:left;">主库不等待备库确认</td><td style="text-align:left;">故障时可能丢失少量事务</td><td style="text-align:left;">低延迟</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 同步复制配置 (synchronous_standby_names)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SYSTEM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> synchronous_standby_names </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;standby1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看复制状态</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_stat_replication;</span></span></code></pre></div><h3 id="复制槽-replication-slot" tabindex="-1" data-src-line="300" data-src-file="postgresql/02-architecture/chapter-02-wal.md">复制槽（Replication Slot） <a class="header-anchor" href="#复制槽-replication-slot" aria-label="Permalink to &quot;复制槽（Replication Slot）&quot;">​</a></h3><p data-src-line="302" data-src-file="postgresql/02-architecture/chapter-02-wal.md">复制槽确保主库保留备库所需的 WAL 文件，不会被清理：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 创建物理复制槽</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_create_physical_replication_slot(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;standby1_slot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 创建逻辑复制槽</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_create_logical_replication_slot(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cdc_slot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pgoutput&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看复制槽状态</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_replication_slots;</span></span></code></pre></div><blockquote data-src-line="315" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><p data-src-line="315" data-src-file="postgresql/02-architecture/chapter-02-wal.md"><strong>⚠️ 警告：</strong> 如果复制槽的消费者长时间断开，主库会保留大量 WAL 文件不清理，导致 <code>pg_wal/</code> 目录暴涨，最终磁盘空间耗尽。务必监控 <code>pg_replication_slots</code> 的 <code>restart_lsn</code> 滞后情况。</p></blockquote>`,59)])])}const k=s(n,[["render",i]]);export{g as __pageData,k as default};
